<?php session_start(); require __DIR__.'/../includes/db.php'; if(!isset($_SESSION['admin_id'])){header('Location: login.php');exit;} ?>
<?php if($_SERVER['REQUEST_METHOD']==='POST'){$id=(int)$_POST['id'];$status=$_POST['status'];$allowed=['Pending','Processing','Shipped','Delivered','Cancelled'];if(in_array($status,$allowed,true)){$st=mysqli_prepare($conn,"UPDATE orders SET status=? WHERE id=?");mysqli_stmt_bind_param($st,'si',$status,$id);mysqli_stmt_execute($st);}}$r=mysqli_query($conn,"SELECT o.*,u.name,u.email FROM orders o JOIN users u ON o.user_id=u.id ORDER BY o.id DESC");?><!DOCTYPE html><html><head><meta charset="UTF-8"><title>Orders</title><link rel="stylesheet" href="../css/style.css"></head><body><?php include __DIR__.'/../includes/admin_navbar.php';?><main class="admin-main"><h1>Orders</h1><table class="admin-table"><tr><th>ID</th><th>User</th><th>Total</th><th>Payment</th><th>Status</th><th>Date</th></tr><?php while($o=mysqli_fetch_assoc($r)): ?><tr><td>#<?php echo $o['id'];?></td><td><?php echo htmlspecialchars($o['name']);?><br><?php echo htmlspecialchars($o['email']);?></td><td>৳<?php echo number_format($o['total_amount'],2);?></td><td><?php echo htmlspecialchars($o['payment_method']);?></td><td><form method="POST"><input type="hidden" name="id" value="<?php echo $o['id'];?>"><select name="status"><option <?php if($o['status']==='Pending')echo'selected';?>>Pending</option><option <?php if($o['status']==='Processing')echo'selected';?>>Processing</option><option <?php if($o['status']==='Shipped')echo'selected';?>>Shipped</option><option <?php if($o['status']==='Delivered')echo'selected';?>>Delivered</option><option <?php if($o['status']==='Cancelled')echo'selected';?>>Cancelled</option></select><button class="btn-small btn-edit">Update</button></form></td><td><?php echo htmlspecialchars($o['created_at']);?></td></tr><?php endwhile;?></table></main></body></html>